    ["Checklist jobs"] = "Checklisten-Aufgaben",
    ["Choose a role first (|cffffff00/fgui setup|r)."] = "Wählt zuerst eine Rolle (|cffffff00/fgui setup|r).",
    ["Choose glass, fantasy or celestial, then a theme. The accent is the highlight color. Everything applies as you click, and all of it can be changed later on the Look tab of /fgui."] = "Wähle Glas, Fantasy oder Himmel, dann ein Thema. Der Akzent ist die Hervorhebungsfarbe. Alles gilt sofort beim Klicken und lässt sich später im Reiter Aussehen von /fgui ändern.",
    ["Choose one of: /fgui raidsort group, /fgui raidsort role, /fgui raidsort name."] = "Wählt eins davon: /fgui raidsort group, /fgui raidsort role, /fgui raidsort name.",
    ["Choose one:"] = "Wähle eine:",
    ["choose the add-on's language"] = "die Sprache des Addons wählen",
    ["Choose which pieces the info bar shows: gold, durability, bags, time and more."] = "Wähle, was die Infoleiste zeigt: Gold, Haltbarkeit, Taschen, Uhrzeit und mehr.",
    ["Choose your features"] = "Wählt Eure Funktionen",
    ["Choosing a language reloads the interface and brings you straight back here."] = "Die Sprachwahl lädt das Interface neu und bringt Euch direkt hierher zurück.",
    ["Choosing cooldowns and buff alerts"] = "Abklingzeiten und Stärkungswarnungen wählen",
