    ["Demo OFF."] = "Demo AUS.",
    ["Demo ON - sample frames and notifications are showing. |cffffff00/fgui demo|r again to end."] = "Demo AN – Beispielrahmen und -meldungen werden gezeigt. |cffffff00/fgui demo|r noch einmal zum Beenden.",
    ["Dense"] = "Dicht",
    ["Deposit"] = "Einlagern",
    ["Deposit materials"] = "Materialien einlagern",
    ["Depositing %d stack of crafting materials."] = "%d Stapel Handwerksmaterial wird eingelagert.",
    ["Depositing %d stacks of crafting materials."] = "%d Stapel Handwerksmaterial werden eingelagert.",
    ["Description"] = "Beschreibung",
    ["Dim my frame when idle"] = "Mein Fenster im Leerlauf abdunkeln",
    ["Dim tracker and info bar in fights"] = "Questverfolgung und Infoleiste im Kampf abdunkeln",
    ["Dimmed"] = "Gedimmt",
    ["Direction"] = "Richtung",
    ["Dismount when an action needs it"] = "Absitzen, wenn eine Aktion es erfordert",
    ["Dispel magic"] = "Magie bannen",
