    ["Profile \"%s\" created."] = "Profil „%s“ erstellt.",
    ["Profile \"%s\" deleted."] = "Profil „%s“ gelöscht.",
    ["Profile \"%s\" imported. Click Use to switch to it."] = "Profil „%s“ eingefügt. Klicke auf Nutzen, um es zu verwenden.",
    ["Profile '%s' made. Click Use to switch to it."] = "Profil '%s' erstellt. Klickt auf Benutzen, um es zu verwenden.",
