    ["Restock: keep %d of %s."] = "Nachkauf: %d von %s behalten.",
    ["Restocked %d of %s."] = "%d x %s nachgekauft.",
    ["Restyled action bars, and a Menu button in place of the game's micro menu."] = "Neu gestaltete Aktionsleisten und ein Menüknopf anstelle des Mikromenüs des Spiels.",
    ["Restyled bars over enemies' heads, colored by threat."] = "Neu gestaltete Leisten über den Köpfen der Feinde, nach Bedrohung gefärbt.",
    ["Restyled tooltips with class colors."] = "Neu gestaltete Tooltips mit Klassenfarben.",
    ["Restyles the character window and all its pages."] = "Gestaltet das Charakterfenster und alle seine Seiten neu.",
    ["Restyles the game's own windows, menus and dialogs to match."] = "Gestaltet die Fenster, Menüs und Dialoge des Spiels passend neu.",
    ["Restyles the spellbook."] = "Gestaltet das Zauberbuch neu.",
