    ["Sharp"] = "Scharf",
    ["Shift"] = "Umschalt",
    ["Shift-click a currency into the line, or give its number: /fgui currency 1166."] = "Fügt eine Währung per Umschalt-Klick in die Zeile ein oder gebt ihre Nummer an: /fgui currency 1166.",
    ["Shift-click a nudge arrow to move ten at a time."] = "Umschalt-Klick auf einen Pfeil verschiebt um zehn.",
    ["Shift-click an item into the line, then a space and how many to keep: /fgui restock [item] 5."] = "Fügt einen Gegenstand per Umschalt-Klick in die Zeile ein, dann ein Leerzeichen und wie viele ihr behalten wollt: /fgui restock [Gegenstand] 5.",
    ["shift-click an item, then a number"] = "Umschalt-Klick auf einen Gegenstand, dann eine Zahl",
    ["Shift-click: the Tools menu"] = "Umschalt-Klick: das Werkzeugmenü",
    ["Shift-right-click: reset the meter"] = "Umschalt-Rechtsklick: Anzeige zurücksetzen",
