    ["%d short"] = "%d manquant(s)",
    ["%d skill points each time."] = "%d points à chaque fois.",
    ["%d skill you can learn now, for %s."] = "%d technique que vous pouvez apprendre, pour %s.",
    ["%d skills you can learn now, %s in all. Buys each one you can afford."] = "%d techniques à apprendre maintenant, %s au total. Achète chacune que vous pouvez payer.",
