    ["Nothing to import."] = "Rien à importer.",
    ["Nothing to show yet: you have not died this session."] = "Rien à montrer : vous n'êtes pas mort dans cette session.",
    ["Nothing to undo."] = "Rien à annuler.",
    ["nothing to work out"] = "rien à calculer",
    ["Nothing was said: %s"] = "Rien n'a été dit : %s",
    ["Nothing yet: each character's week is noted as you play it."] = "Rien pour l'instant : la semaine de chaque personnage est notée pendant que vous le jouez.",
    ["Nothing yet: the meter fills during a fight."] = "Rien pour l'instant : le compteur se remplit pendant un combat.",
    ["Nothing yet: what bosses drop is noted as you kill them, in raids and dungeons."] = "Rien pour l'instant : ce que lâchent les boss est noté quand vous les tuez, en raid et en donjon.",
    ["Nothing you know gives skill points any more: time to learn new recipes from a trainer."] = "Plus rien de ce que vous connaissez ne donne de points : il est temps d'apprendre de nouvelles recettes auprès d'un maître.",
    ["Notifications"] = "Notifications",
    ["Notifications (loot, mail, warnings)"] = "Notifications (butin, courrier, alertes)",
