    ["%dd %dh"] = "%d d %d h",
    ["%dd %dh %02dm"] = "%d d %d h %02d min",
    ["%dh %02dm"] = "%d h %02d min",
    ["%dh %dm"] = "%dh %dm",
    ["%dm"] = "%d min",
    ["%dm %02ds"] = "%d min %02d s",
    ["%s an hour"] = "%s por hora",
    ["%s an hour (%s gold, %s items)"] = "%s por hora (%s en oro, %s en objetos)",
    ["%s asks if you are ready."] = "%s pregunta si estás listo.",
    ["%s bosses killed"] = "%s jefes derrotados",
    ["%s can drop from your wishlist: %s"] = "%s puede soltar algo de tu lista de deseos: %s",
    ["%s dungeon and raid runs"] = "%s incursiones en mazmorras y bandas",
    ["%s each"] = "%s cada uno",
    ["%s experience"] = "%s de experiencia",
    ["%s gold made"] = "%s de oro ganado",
    ["%s gold on all characters"] = "%s de oro en todos los personajes",
    ["%s has not answered: they may be offline, or not have Fantasy Glass UI."] = "%s no ha respondido: puede estar desconectado o no tener Fantasy Glass UI.",
    ["%s has your %s."] = "%s tiene tu %s.",
    ["%s in place. /fgui move to fine-tune, /fgui undo to go back."] = "%s colocado. /fgui move para afinar, /fgui undo para volver.",
    ["%s is in combat: the resurrection is left for you to accept."] = "%s está en combate: la resurrección queda a tu decisión.",
    ["%s is now on %s"] = "%s está ahora en %s",
    ["%s is now on %s (it was on %s)"] = "%s está ahora en %s (antes: %s)",
    ["%s is now your main: new characters copy its setup (|cffffff00/fgui main off|r to undo)."] = "%s es ahora tu personaje principal: los personajes nuevos copian su configuración (|cffffff00/fgui main off|r para deshacerlo).",
    ["%s is off both lists."] = "%s ya no está en ninguna de las dos listas.",
    ["%s is switched off; it goes after a /reload."] = "%s está desactivado; desaparece tras un /reload.",
    ["%s is your main."] = "%s es tu personaje principal.",
    ["%s items looted"] = "%s objetos saqueados",
    ["%s joined the group."] = "%s se ha unido al grupo.",
    ["%s kills"] = "%s muertes causadas",
    ["%s left the group."] = "%s ha dejado el grupo.",
    ["%s quests done"] = "%s misiones completadas",
    ["%s saved; it takes its place after the fight (or a /reload)."] = "%s guardado; ocupa su lugar tras el combate (o un /reload).",
    ["%s sent the group a note for %s."] = "%s ha enviado al grupo una nota para %s.",
    ["%s sent you a %s. Look it over in the preview, then choose Use it or close it."] = "%s te ha enviado: %s. Revísalo en la vista previa y elige Usarlo o ciérralo.",
    ["%s sent you a talent build for another class (%s): it was not kept."] = "%s te ha enviado una configuración de talentos de otra clase (%s): no se ha guardado.",
    ["%s sent you a talent build: \"%s\". It is with your builds (/fgui talents); nothing is learned until you choose it."] = "%s te ha enviado una configuración de talentos: «%s». Está con las tuyas (/fgui talents); no se aprende nada hasta que la elijas.",
    ["%s will always be sold with your junk."] = "%s siempre se venderá con tu basura.",
    ["%s will never be sold with your junk."] = "%s nunca se venderá con tu basura.",
    ["%s: \"%s\" is not on the list."] = "%s: «%s» no está en la lista.",
    ["%s: %d%%, from when the fight ends."] = "%s: %d%%, cuando termine el combate.",
    ["%s: %d%%."] = "%s: %d%%.",
    ["%s: %d%%. Give a number from %d to %d."] = "%s: %d%%. Indica un número del %d al %d.",
    ["%s: %s (best %s)"] = "%s: %s (récord %s)",
    ["%s: %s (first time timed)"] = "%s: %s (primera vez cronometrada)",
    ["%s: %s - a new best (was %s)"] = "%s: %s - nuevo récord (antes %s)",
    ["%s: %s left"] = "%s: quedan %s",
    ["%s: added \"%s\"."] = "%s: «%s» añadido.",
    ["%s: keys cleared"] = "%s: teclas borradas",
    ["%s: not during a fight, so it happens as soon as the fight ends."] = "%s: no en combate, así que en cuanto termine el combate.",
    ["%s: not this time, after %s."] = "%s: esta vez no, tras %s.",
    ["%s: removed \"%s\"."] = "%s: «%s» quitado.",
    ["%s: the list is empty."] = "%s: la lista está vacía.",
    ["(%d more)"] = "(%d más)",
    ["(auction)"] = "(subasta)",
    ["(not over an action button)"] = "(no sobre un botón de acción)",
    ["(not set)"] = "(sin definir)",
    ["* On another realm: only possible if the game allows mail between those realms."] = "* En otro reino: solo si el juego permite el correo entre esos reinos.",
    ["... and %d more"] = "... y %d más",
    ["/fgui bagrules add ilvl 50 = Upgrades   (kinds: ilvl, boe, set, quality, type, name)"] = "/fgui bagrules add ilvl 50 = Mejoras   (tipos: ilvl, boe, set, quality, type, name)",
    ["/fgui check lists what this game client supports and any errors. /fgui report gathers everything for a problem report. /fgui safe reloads with every feature off, to see whether the add-on is the cause."] = "/fgui check muestra lo que admite este cliente y los errores. /fgui report reúne todo para un informe de problema. /fgui safe recarga con todo desactivado para ver si el addon es la causa.",
    ["/fgui check new tries each feature added since 11.6 and reports what works."] = "/fgui check new prueba cada función añadida desde la 11.6 e informa de lo que funciona.",
    ["/fgui crafts <part of a name> searches every character's recipes."] = "/fgui crafts <parte de un nombre> busca en las recetas de todos tus personajes.",
    ["/fgui farm starts a session: a small panel shows the time and what you make an hour, in gold and in the items you loot (the auction price you have seen, or the vendor's). /fgui farm again lists every item; /fgui farm stop ends it, and the session counts in your weekly recap."] = "/fgui farm empieza una sesión: un pequeño panel muestra el tiempo y lo que ganas por hora, en oro y en los objetos que saqueas (el precio de subasta que has visto, o el del vendedor). /fgui farm otra vez lista cada objeto; /fgui farm stop la termina, y la sesión cuenta en tu resumen semanal.",
    ["/fgui gear lists everyone in your party or raid with their item level, the lowest first, and the group's average. The game sends another player's gear one player at a time and only within reach, so the list fills in while it is open; it never asks during a fight or while your own inspect window is open."] = "/fgui gear lista a todos en tu grupo o banda con su nivel de objeto, el más bajo primero, y la media del grupo. El juego envía el equipo de otro jugador de uno en uno y solo al alcance, así que la lista se llena mientras está abierta; nunca pregunta en combate ni con tu ventana de inspección abierta.",
    ["/fgui help opens a window you can search, and the Tools menu is sorted into groups."] = "/fgui help abre una ventana donde buscar, y el menú Herramientas está ordenado en grupos.",
    ["/fgui loot clear empties the list."] = "/fgui loot clear vacía la lista.",
    ["/fgui mailrules add <character> <what>   what: cloth, leather, ore, herbs, cooking, elemental, enchanting, gems, potions, name:<text>"] = "/fgui mailrules add <personaje> <qué>   qué: cloth, leather, ore, herbs, cooking, elemental, enchanting, gems, potions, name:<texto>",
    ["/fgui main makes this character your main. Also: |cffffff00/fgui main off|r, |cffffff00share|r, |cffffff00copy|r."] = "/fgui main convierte a este personaje en tu principal. También: |cffffff00/fgui main off|r, |cffffff00share|r, |cffffff00copy|r.",
    ["/fgui move drags it; right-click it there for its scale."] = "/fgui move para moverlo; clic derecho allí para su escala.",
    ["/fgui new shows the note for the last few versions. /fgui help lists every command."] = "/fgui new muestra las notas de las últimas versiones. /fgui help muestra todos los comandos.",
    ["/fgui reset puts the current profile back to how the add-on comes. /fgui windows reset only puts the game's windows back where they open."] = "/fgui reset deja el perfil actual como viene el addon. /fgui windows reset solo devuelve las ventanas del juego a su sitio.",
    ["/fgui rolls clear starts a new round."] = "/fgui rolls clear empieza una ronda nueva.",
    ["/fgui setup (or Run setup again below) opens the guided setup: role, look, lettering, layout."] = "/fgui setup (o Volver a configurar abajo) abre la configuración guiada: rol, aspecto, tipografía, disposición.",
    ["/fgui stats: one page of totals for this character and for all of them together - time played, levels, quests, kills, deaths, gold made and spent, items looted, bosses killed, dungeon and raid runs with their best times, and time spent farming. The counts start the day this version first runs."] = "/fgui stats: una página de totales para este personaje y para todos juntos - tiempo jugado, niveles, misiones, muertes causadas, muertes, oro ganado y gastado, objetos saqueados, jefes derrotados, incursiones con sus mejores tiempos y tiempo de farmeo. Se cuenta desde el día en que esta versión se ejecuta por primera vez.",
    ["/fgui talents send <player> <build name>"] = "/fgui talents send <jugador> <nombre de la configuración>",
    ["/fgui undo (or Ctrl+Z while moving panels) puts back the last move, resize or reset, thirty steps deep."] = "/fgui undo (o Ctrl+Z al mover paneles) deshace el último movimiento, cambio de tamaño o restablecimiento, hasta treinta pasos.",
    ["/fgui windows reset - the game's windows open in their usual places again"] = "/fgui windows reset: las ventanas del juego vuelven a abrirse en su sitio de siempre",
    ["/rl reloads the interface, /rc starts a ready check, /tt whispers your target. Each is left alone if another add-on already has it."] = "/rl recarga la interfaz, /rc inicia una comprobación, /tt susurra a tu objetivo. Cada uno se deja si otro accesorio ya lo tiene.",
    ["2D picture"] = "Imagen 2D",
    ["3D model"] = "Modelo 3D",
    ["50 = Upgrades"] = "50 = Mejoras",
    ["A \"Send by my rules\" button above the mail window whenever there is something to send. It sends everything below that is switched on, twelve items to a letter."] = "Un botón «Enviar según mis reglas» sobre la ventana de correo cuando hay algo que enviar. Envía todo lo activado abajo, doce objetos por carta.",
    ["a %s screen"] = "una pantalla %s",
    ["A 10 second pull countdown for the group (/fgui pull 15 for another length)."] = "Una cuenta atrás de pull de 10 segundos para el grupo (/fgui pull 15 para otra duración).",
    ["A 5 minute break for the group (/fgui break 10 for another length)."] = "Un descanso de 5 minutos para el grupo (/fgui break 10 para otra duración).",
    ["a bag section by rule (ilvl, boe, set, quality, type, name)"] = "una sección de bolsa por regla (ilvl, boe, set, quality, type, name)",
    ["A banner when a quest is accepted or completed, and a hint at the best-selling reward."] = "Un cartel al aceptar o completar una misión y una pista de la recompensa que más vale.",
    ["A bar with the time left on a flight path. A route's time is learned the first time you fly it; until then the bar counts up."] = "Una barra con el tiempo restante de un vuelo. El tiempo de una ruta se aprende la primera vez que la vuelas; hasta entonces la barra cuenta hacia arriba.",
    ["A break is from 1 to 60 minutes."] = "Un descanso va de 1 a 60 minutos.",
    ["A buff missing from me"] = "Me falta un beneficio",
    ["A buff on me"] = "Un beneficio sobre mí",
    ["a buff or debuff's name"] = "nombre de un beneficio o perjuicio",
    ["a buff's name"] = "nombre de un beneficio",
    ["A button that appears while something in your bags can be opened (a clam, a bag of loot, an unlocked lockbox). Each click opens one."] = "Un botón que aparece mientras algo de tus bolsas se puede abrir (una almeja, una bolsa de botín, una caja fuerte abierta). Cada clic abre uno.",
    ["a calculator"] = "una calculadora",
    ["A cast bar under each enemy nameplate."] = "Una barra de lanzamiento bajo cada placa de nombre enemiga.",
    ["A character you have never played before gets its own profile, copied from your main and fitted to its class. Off: new characters share the Default profile."] = "Un personaje que nunca jugaste recibe su propio perfil, copiado de tu principal y adaptado a su clase. Desactivado: los nuevos comparten el perfil Default.",
    ["A character's lockouts are read when you log in with it."] = "Los bloqueos de un personaje se leen al entrar con él.",
    ["a character's name"] = "nombre de un personaje",
    ["A chime when one of a quest's objectives is finished, and the quest-complete sound when the whole quest is ready to hand in."] = "Un tintineo cuando se cumple un objetivo de una misión, y el sonido de misión completa cuando toda la misión se puede entregar.",
    ["a countdown bar (also 90s, 1h30m, 2:30; \"off\" cancels them all)"] = "una barra de cuenta atrás (también 90s, 1h30m, 2:30; «off» las cancela todas)",
    ["A damage and healing meter, on clients that share those totals. Views: damage and healing per second, damage and healing done, damage taken, absorbs, interrupts, dispels and deaths. Click its heading (or roll the mouse wheel over it) for the next view, right-click for this fight, overall or an earlier fight, Shift-right-click to reset. Point at a row for that player's abilities. Your own row has a white edge. Under the bars: who has how much threat on your target when you are in a group."] = "Un medidor de daño y sanación, en clientes que comparten esos totales. Vistas: daño y sanación por segundo, daño y sanación realizados, daño recibido, absorciones, interrupciones, disipaciones y muertes. Haz clic en su encabezado (o gira la rueda encima) para la siguiente vista, clic derecho para este combate, total o uno anterior, Mayús-clic derecho para reiniciar. Señala una fila para ver las habilidades de ese jugador. Tu fila tiene borde blanco. Bajo las barras: quién tiene cuánta amenaza sobre tu objetivo en grupo.",
    ["A debuff icon on each player"] = "Un icono de perjuicio en cada jugador",
    ["A diamond minimap, cut like the Starcut portrait, with a fine rim and a star on each point. It takes the place of round or square while it is on. The zone, coordinates and clock stay on it."] = "Un minimapa en rombo, tallado como el retrato de Talla estelar, con un borde fino y una estrella en cada punta. Mientras está activo sustituye al redondo o cuadrado. La zona, las coordenadas y el reloj siguen en él.",
    ["a farming session: time, and gold and item value an hour; again to see it, stop to end it, zones for your best spots"] = "una sesión de farmeo: tiempo, y oro y valor de objetos por hora; otra vez para verla, stop para terminarla, zones para tus mejores lugares",
    ["A few seconds after you log in, one small window says what is waiting: crafts ready, mail on your other characters, lockouts that have reset, rested experience and the jobs left on your checklist. Only when something is waiting; /fgui briefing shows it at any time."] = "Unos segundos después de conectarte, una ventanita dice lo que te espera: fabricaciones listas, correo en otros personajes, bloqueos reiniciados, experiencia de descanso y tareas pendientes. Solo si algo espera; /fgui briefing lo muestra en cualquier momento.",
    ["A fight started: the rest of the build waits. Choose it again afterwards."] = "Ha empezado un combate: el resto espera. Elígela de nuevo después.",
    ["A friend or guildmate who whispers you the word inv is invited to your group, whenever you are able to invite. /fgui invword changes the word. Presets never change this."] = "Un amigo o miembro de hermandad que te susurre la palabra inv es invitado a tu grupo cuando puedas invitar. /fgui invword cambia la palabra. Los ajustes predefinidos nunca lo cambian.",
    ["A glossy texture on health and power bars instead of a flat one."] = "Una textura brillante en lugar de una plana en las barras de salud y recurso.",
    ["a goal of your own on the goals panel (click it to count); /fgui goal ach <achievement> too"] = "un objetivo propio en el panel de objetivos (haz clic para contar); también /fgui goal ach <logro>",
    ["A green arrow on gear with a higher item level than what you wear in that slot: on loot rolls, quest rewards and the game's own bags (the one-window bags always have it). Item tooltips say by how much. /fgui equipbest puts on every upgrade that is already bound to you."] = "Una flecha verde en el equipo con más nivel que el que llevas en esa ranura: en tiradas de botín, recompensas de misión y las bolsas del juego (las bolsas de una ventana siempre la tienen). Las descripciones dicen cuánto. /fgui equipbest se pone cada mejora ya ligada.",
    ["A group gear check: /fgui gear lists everyone in your group with their item level, the lowest first, and the group's average."] = "Una revisión de equipo: /fgui gear lista a todos en tu grupo con su nivel de objeto, el más bajo primero, y la media.",
    ["A helpful spell cast with no friendly target lands on you instead of asking for a target. A game setting: switching this off puts back what it was. Presets never change this."] = "Un hechizo de ayuda lanzado sin objetivo amistoso te alcanza a ti en lugar de pedir objetivo. Un ajuste del juego: desactivarlo restaura lo que había. Los ajustes predefinidos nunca lo cambian.",
    ["A holiday that is on in the game's calendar is added to your checklist as a daily job, and taken off when it ends. /fgui events lists what is on now and in the next two weeks."] = "Una festividad activa en el calendario del juego se añade a tu lista como tarea diaria y se quita al acabar. /fgui events lista lo que hay ahora y en las próximas dos semanas.",
    ["a job, such as Cooking quest"] = "una tarea, como la misión de cocina",
    ["A key binding (Key Bindings, AddOns) for the best way home that is ready: your hearthstone, then Astral Recall, then a teleport. /fgui home says which it would use."] = "Un atajo (Asignación de teclas, AddOns) para la mejor vuelta a casa disponible: tu piedra de hogar, luego Regreso astral, luego un teletransporte. /fgui home dice cuál usaría.",
    ["A large icon with a countdown while you are stunned, silenced, feared or otherwise not in control. Place it in move mode."] = "Un icono grande con cuenta atrás mientras estás aturdido, silenciado, asustado o sin control. Colócalo en el modo mover.",
    ["A layout"] = "Un diseño",
    ["A layout is only where panels sit and how big they are. Export gives a text string to copy; to use someone else's, paste it in the box and press Import."] = "Un diseño es solo dónde están los paneles y su tamaño. Exportar da un texto para copiar; para usar el de otra persona, pégalo en el cuadro y pulsa Importar.",
    ["A line in chat and a sound when someone joins or leaves your group, and when a party is full."] = "Una línea en el chat y un sonido cuando alguien entra o sale del grupo, y cuando está completo.",
    ["A login briefing: a few seconds after you log in, one small window says what is waiting: crafts ready, mail on your other characters, lockouts reset, rested experience, jobs left. /fgui briefing shows it again."] = "Un resumen al entrar: unos segundos después de conectarte, una pequeña ventana dice lo que te espera: fabricaciones listas, correo en otros personajes, bloqueos reiniciados, experiencia de descanso, tareas pendientes. /fgui briefing lo muestra de nuevo.",
    ["A loot browser: /fgui drops lists what each boss dropped while you were there, raid by raid, with the upgrades for you first."] = "Un explorador de botín: /fgui drops lista lo que soltó cada jefe mientras estabas allí, banda por banda, con las mejoras para ti primero.",
    ["A Loot tab and a Whispers tab."] = "Una pestaña de Botín y otra de Susurros.",
    ["A loot wishlist: click an item in the loot browser to star it, and you are told when it drops, comes up in a roll, or a boss that drops it is your target. /fgui wish lists them."] = "Una lista de deseos de botín: haz clic en un objeto del explorador de botín para marcarlo, y se te avisa cuando cae, sale a tirada o un jefe que lo suelta es tu objetivo. /fgui wish los lista.",
    ["a name"] = "un nombre",
    ["a name for the guide"] = "un nombre para la guía",
    ["a name for the section"] = "un nombre para la sección",
    ["a name for your talents now"] = "un nombre para tus talentos actuales",
    ["A new look for your unit frames, Starcut: bars cut to points that glow in their own color, a diamond portrait with stars on its points, and the name above the bars."] = "Un aspecto nuevo para tus marcos de unidad, Talla estelar: barras talladas en punta que brillan con su propio color, un retrato en rombo con estrellas en sus puntas y el nombre encima de las barras.",
    ["A new profile from the %s template"] = "Un perfil nuevo de la plantilla %s",
    ["A new profile that starts as a copy of the one you are using."] = "Un perfil nuevo que empieza como copia del que usas.",
    ["A night sky: a fine starfield, constellations and star points in the accent color."] = "Un cielo nocturno: un fino campo de estrellas, constelaciones y destellos en el color de acento.",
    ["A note for each boss: a tactic, who soaks, when to use a cooldown. It opens when you target the boss, when the fight starts, or with a pull timer. /fgui bossnote writes one; the group's leader can send theirs to the group."] = "Una nota para cada jefe: una táctica, quién absorbe, cuándo usar una reutilización. Se abre al seleccionar al jefe, al empezar el combate o con un temporizador de pull. /fgui bossnote escribe una; el líder puede enviar la suya al grupo.",
    ["a note on the player you have targeted (\"list\" shows them all)"] = "una nota sobre el jugador seleccionado («list» las muestra todas)",
    ["A note when your weapon imbue (or poison) is missing or about to run out."] = "Un aviso cuando falta la imbuición de tu arma (o el veneno) o está por acabarse.",
    ["a notepad for this character and one for all"] = "un bloc de notas para este personaje y otro para todos",
    ["A number"] = "Un número",
    ["a number"] = "un número",
    ["a player's name"] = "nombre de un jugador",
    ["A profile called \"%s\" already exists."] = "Ya existe un perfil llamado «%s».",
    ["a pull countdown for everyone in the group (/fgui break 5 is a break, in minutes)"] = "una cuenta atrás de pull para todo el grupo (/fgui break 5 es un descanso, en minutos)",
    ["A pull timer is from 1 to 60 seconds."] = "Un temporizador de pull va de 1 a 60 segundos.",
    ["A quest guide is on its way: routes you follow one step at a time, with a panel for the step you are on and an arrow that points to it."] = "Una guía de misiones está en camino: rutas que sigues paso a paso, con un panel para el paso actual y una flecha que lo señala.",
    ["A quiet screen: frames low, action bars only in combat, no background behind the info bar."] = "Una pantalla tranquila: marcos tenues, barras de acción solo en combate, sin fondo tras la barra de información.",
    ["a random favorite mount, or off the one you are on"] = "una montura favorita al azar, o bajarte de la tuya",
    ["a random favorite pet (/fgui mount for a mount)"] = "una mascota favorita al azar (/fgui mount para una montura)",
    ["a report on what is running and what the game allows"] = "un informe de lo que se ejecuta y lo que el juego permite",
    ["a report to copy if something looks wrong"] = "un informe para copiar si algo va mal",
    ["A ring in the accent color round the mouse pointer, so it is easy to find in a fight. It hides while you hold a mouse button to turn or look around."] = "Un anillo del color de acento alrededor del puntero, para encontrarlo fácil en combate. Se oculta mientras mantienes un botón para girar o mirar.",
    ["A round minimap instead of the square one, with a rim in your theme's color. The zone, coordinates and clock stay on it."] = "Un minimapa redondo en lugar del cuadrado, con un borde del color de tu tema. La zona, las coordenadas y el reloj siguen en él.",
    ["A row of buttons under the character window, one for each set saved in the game's equipment manager. Click one to put that set on. The set you are wearing is underlined; a set with pieces you no longer have is gray. Not in combat."] = "Una fila de botones bajo la ventana del personaje, uno por cada conjunto guardado en el gestor de equipo. Haz clic para ponértelo. El que llevas está subrayado; uno con piezas que ya no tienes sale gris. No en combate.",
    ["A row of these abilities with their cooldowns. Type each spell's name exactly as in your spellbook. Spells you don't know are skipped."] = "Una fila de estas habilidades con sus reutilizaciones. Escribe cada hechizo tal como en tu libro. Los que no conozcas se omiten.",
    ["A row of your abilities that have a cooldown, each showing when it is ready. One click fills it from your action bars; you can edit the list later on the Combat tab."] = "Una fila de tus habilidades con reutilización, cada una indica cuándo está lista. Un clic la llena desde tus barras; puedes editar la lista luego en la pestaña Combate.",
    ["A run log: /fgui runs keeps your dungeon and raid times, kills, wipes, deaths and loot, with a best time for each place."] = "Un registro de incursiones: /fgui runs guarda tus tiempos en mazmorras y bandas, jefes muertos, wipes, muertes y botín, con un mejor tiempo para cada lugar.",
    ["A separate layout for each screen size"] = "Un diseño para cada tamaño de pantalla",
    ["A separate layout for each talent set"] = "Un diseño para cada grupo de talentos",
    ["A separate layout for solo, party and raid"] = "Una disposición distinta en solitario, grupo y banda",
    ["A short notice and a sound when you reach a milestone: 100, 1,000, 10,000 kills; 100 quests; your first boss and your 100th; your first run; 1,000 gold made; and more. They are listed with the day on the stats page (/fgui stats). Needs Lifetime stats."] = "Un aviso breve y un sonido al alcanzar un hito: 100, 1.000, 10.000 muertes causadas; 100 misiones; tu primer jefe y el número 100; tu primera incursión; 1.000 de oro ganado; y más. Se listan con la fecha en la página de estadísticas (/fgui stats). Necesita Estadísticas totales.",
    ["A short report to copy into a bug report: version, client, errors and the switches you changed."] = "Un informe breve para copiar en un aviso de error: versión, cliente, errores y opciones cambiadas.",
    ["A short tour of the choices worth making; about two minutes. Each choice applies as you click where it can, and all of it can be changed later in /fgui."] = "Un breve recorrido por las decisiones que valen la pena; unos dos minutos. Cada elección se aplica al hacer clic cuando se puede, y todo se cambia luego en /fgui.",
    ["A Skill-ups button on the profession window: the recipes you know that still give skill points, best first. What you can make now comes first, then what needs the fewest materials (counting your other characters), orange before yellow before green."] = "Un botón «Subir habilidad» en la ventana de profesión: las recetas que conoces que aún dan puntos, las mejores primero. Primero lo que puedes fabricar ya, luego lo que menos materiales necesita (contando tus otros personajes), naranja antes que amarillo y verde.",
    ["A slim experience and reputation bar; hover it for pace and time to level."] = "Una barra fina de experiencia y reputación; pasa el ratón para ver el ritmo y el tiempo hasta el nivel.",
    ["A small 1 and 2 at the top of the character window: one click changes talent set (also /fgui spec)."] = "Un pequeño 1 y 2 arriba en la ventana del personaje: un clic cambia de talentos (también /fgui spec).",
    ["A small bar at the top of the screen while you wait for a battleground: how long you have waited and the game's estimate, then how long the invitation has left. When you are in, a countdown to the start of the battle. /fgui bgscore shows the score."] = "Una pequeña barra arriba mientras esperas un campo de batalla: cuánto llevas esperando y la estimación del juego, luego lo que le queda a la invitación. Dentro, una cuenta atrás hasta el inicio. /fgui bgscore muestra la puntuación.",
    ["A small bar in a group saying who is next to interrupt, and telling you (on screen, and aloud if spoken alerts are on) when it is you. Set the order with /fgui kicks <name> <name>; the group leader's order is shared. Needs the group cooldowns from players with Fantasy Glass UI. /fgui testgroup shows it with made-up group mates."] = "Una pequeña barra en grupo que dice quién interrumpe después y te avisa (en pantalla, y en voz alta si los avisos hablados están activados) cuando te toca. Fija el orden con /fgui kicks <nombre> <nombre>; se comparte el orden del líder. Necesita las reutilizaciones de grupo de jugadores con Fantasy Glass UI. /fgui testgroup lo muestra con compañeros inventados.",
    ["A small bar that fills itself with the potions, bandages, food and drink, flasks, elixirs and scrolls in your bags, one button each, with how many you have. Click to use. It is laid out again between fights; place it in move mode."] = "Una pequeña barra que se llena con las pociones, vendas, comida y bebida, frascos, elixires y pergaminos de tus bolsas, un botón cada uno con cuántos tienes. Haz clic para usar. Se reorganiza entre combates; colócala en el modo de mover.",
    ["A small button on the minimap with the add-on's icon. Left-click opens these options, right-click starts moving panels, and it can be dragged along the minimap."] = "Un pequeño botón en el minimapa con el icono del accesorio. Clic izquierdo abre estas opciones, clic derecho empieza a mover paneles, y se puede arrastrar por el minimapa.",
    ["A small display in the middle of the screen for your role: threat, party health, or target health."] = "Un pequeño indicador en el centro de la pantalla para tu rol: amenaza, salud del grupo o salud del objetivo.",
    ["A small frame for whatever your focus is targeting, like the target's target frame. It appears only while your focus has a target."] = "Un pequeño marco para el objetivo de tu foco, como el de objetivo del objetivo. Solo aparece mientras tu foco tiene objetivo.",
    ["A small icon on the raid and party frames of anyone missing the buff you can give (Fortitude, Mark of the Wild, Arcane Intellect, Battle Shout). Checked out of fights. /fgui testgroup shows it on sample frames."] = "Un pequeño icono en los marcos de banda y grupo de quien no tenga el beneficio que puedes dar (Entereza, Marca de lo Salvaje, Intelecto Arcano, Grito de batalla). Se comprueba fuera de combate. /fgui testgroup lo muestra en marcos de ejemplo.",
    ["A small panel for ready checks, pull timers and markers when you lead a group."] = "Un pequeño panel para comprobaciones, temporizadores de pull y marcadores cuando lideras un grupo.",
    ["A small panel of its own: in a group, with a hostile target, who has how much threat on it, most first, up to five of you. Your row turns the warning color near the top and the danger color when you would pull the target. Works without the damage meter. Move it with /fgui move."] = "Un pequeño panel propio: en grupo, con un objetivo hostil, quién tiene cuánta amenaza sobre él, de más a menos, hasta cinco de vosotros. Tu fila toma el color de aviso cerca de la cima y el de peligro cuando te llevarías el objetivo. Funciona sin el medidor de daño. Muévelo con /fgui move.",
    ["A small panel of what you are working towards, with a bar each: reputations (/fgui goal rep <name>), gold on all your characters (/fgui goal gold 10000), a level (/fgui goal level 60), a mount (/fgui goal mount <name>), achievements, your own goals, and items (/fgui goal and a shift-clicked item with a number), counted on all your characters, with where a boss drop drops in its tooltip. A goal reached says so once."] = "Un pequeño panel de lo que persigues, con una barra cada uno: reputaciones (/fgui goal rep <nombre>), oro en todos tus personajes (/fgui goal gold 10000), un nivel (/fgui goal level 60), una montura (/fgui goal mount <nombre>), logros, tus propias metas y objetos (/fgui goal con un objeto en Mayús-clic y un número), contados en todos tus personajes, con dónde cae un botín de jefe en su descripción. Una meta alcanzada se anuncia una vez.",
    ["A small panel with the time on the current boss and the time since you entered the dungeon or raid. When a boss dies you are told the time and your best, from the run log (/fgui runs), so the two always agree."] = "Un pequeño panel con el tiempo en el jefe actual y desde que entraste en la mazmorra o banda. Al morir un jefe se te dice el tiempo y tu mejor marca, del registro de incursiones (/fgui runs), para que ambos coincidan siempre.",
    ["A small panel, in a group, listing who has a battle resurrection, an interrupt, a big defensive or a raid cooldown, and whether it is ready or how long until it is. Group members with Fantasy Glass UI tell each other (whether or not this panel is on); others are not listed."] = "Un pequeño panel, en grupo, con quién tiene resurrección en combate, interrupción, una gran defensiva o una reutilización de banda, y si está lista o cuánto falta. Los miembros con Fantasy Glass UI se lo comunican (esté o no este panel); los demás no aparecen.",
    ["A small timer that counts how long the fight has lasted, whatever your role. It shows the final time for a few seconds afterwards, then goes. It can be moved like any panel."] = "Un pequeño cronómetro que cuenta cuánto dura el combate, sea cual sea tu rol. Muestra el tiempo final unos segundos y desaparece. Se mueve como cualquier panel.",
    ["A sound and a line in the middle of the screen when an enemy you have as your focus starts a cast."] = "Un sonido y una línea en el centro de la pantalla cuando el enemigo en tu foco empieza a lanzar.",
    ["A sound when a step is done"] = "Un sonido al completar un paso",
    ["A square minimap with zone, coordinates and clock."] = "Un minimapa cuadrado con zona, coordenadas y reloj.",
    ["A theme"] = "Un tema",
    ["A thin bar at the top: frame rate, latency, durability, gold and time."] = "Una barra fina arriba: fotogramas, latencia, durabilidad, oro y hora.",
    ["A thin line on the target's health bar at a percentage you choose, 20 unless you change it with /fgui execute."] = "Una línea fina en la barra de salud del objetivo al porcentaje que elijas, 20 salvo que lo cambies con /fgui execute.",
    ["A third family of themes: Runic. 38 themes of carved stone with an engraved edge and runes glowing in the accent color (Look tab, or the setup)."] = "Una tercera familia de temas: Rúnico. 38 temas de piedra tallada con borde grabado y runas que brillan en el color de acento (pestaña Aspecto, o la configuración).",
    ["A threat meter of its own: in a group, who has how much threat on your target, and a warning color as you near the top."] = "Un medidor de amenaza propio: en grupo, quién tiene cuánta amenaza sobre tu objetivo, con un color de aviso cuando te acercas a la cima.",
    ["a to-do list (\"daily ...\" comes back each day)"] = "una lista de tareas («daily ...» vuelve cada día)",
    ["A vendor pays %s each."] = "Un vendedor paga %s cada uno.",
    ["A warning when a monster turns on you in a group and you are not the tank."] = "Un aviso cuando un monstruo se vuelve contra ti en grupo y no eres el tanque.",
    ["a waypoint with an arrow and the distance (alone, it clears)"] = "un punto de ruta con flecha y distancia (solo, lo borra)",
    ["A whole profile"] = "Un perfil completo",
    ["A whole-UI pack"] = "Un paquete de interfaz completa",
    ["a word"] = "una palabra",
    ["A word in the middle of the screen as a fight starts (+ Combat) and as it ends (- Combat), gone in a moment. Place it in move mode."] = "Una palabra en el centro de la pantalla al empezar (+ Combat) y terminar (- Combat) un combate, que desaparece enseguida. Colócala en el modo de mover.",
    ["A yellow ! beside the nameplate of anything you still need for a quest, so it can be picked out of a pack at a glance."] = "Un ! amarillo junto a la placa de nombre de lo que aún necesitas para una misión, para distinguirlo de un vistazo.",
    ["Abandon"] = "Abandonar",
    ["Above the frame"] = "Encima del marco",
    ["Absorbed"] = "Absorbido",
    ["Absorbs"] = "Absorciones",
    ["Accent"] = "Acento",
    ["Accent and style"] = "Acento y estilo",
    ["Accent color"] = "Color de acento",
    ["Accent color: your frames. Green: party and raid. Gray: the rest. /fgui undo takes a setup back."] = "Color de acento: tus marcos. Verde: grupo y banda. Gris: el resto. /fgui undo deshace una disposición.",
    ["Accept"] = "Aceptar",
    ["Accept invites from friends & guild"] = "Aceptar invitaciones de amigos y hermandad",
    ["Accept resurrections"] = "Aceptar resurrecciones",
    ["Accept role checks"] = "Aceptar comprobaciones de rol",
    ["Accept setups other players send me"] = "Aceptar configuraciones que me envíen",
    ["Accept summons"] = "Aceptar invocaciones",
    ["Accepts a group invitation by itself when it comes from a friend, a Battle.net friend or a guildmate. Anyone else's invitation is left for you to answer. Presets never change this."] = "Acepta sola una invitación de grupo si viene de un amigo, amigo de Battle.net o miembro de hermandad. Las de los demás las respondes tú. Los ajustes predefinidos nunca lo cambian.",
    ["Accepts a resurrection for you. One cast by someone who is in a fight is left on screen for you to time yourself. Hold Shift as the offer arrives to answer it yourself. Presets never change this."] = "Acepta una resurrección por ti. Si la lanza alguien en combate, se deja en pantalla para que elijas el momento. Mantén Mayús al llegar para responder tú. Los ajustes predefinidos nunca lo cambian.",
    ["Accepts a summon for you after five seconds, saying in chat who it is from and where it leads. Decline it in that time to stay; hold Shift as it arrives to answer it yourself. Presets never change this."] = "Acepta una invocación por ti a los cinco segundos, diciendo en el chat de quién es y adónde lleva. Recházala en ese tiempo para quedarte; mantén Mayús al llegar para responder tú. Los ajustes predefinidos nunca lo cambian.",
    ["Accepts and turns in quests for you without asking."] = "Acepta y entrega misiones por ti sin preguntar.",
    ["Across"] = "Horizontal",
    ["Action bar size %"] = "Tamaño de las barras de acción %",
    ["Action bars"] = "Barras de acción",
    ["Action bars: key text"] = "Barras de acción: texto de teclas",
    ["Action bars: macro names"] = "Barras de acción: nombres de macros",
    ["Active profile:"] = "Perfil activo:",
    ["Add"] = "Añadir",
    ["Add after it"] = "Añadir después",
    ["add the selected recipe to the crafting queue; /fgui queue list shows it"] = "añadir la receta elegida a la cola de fabricación; /fgui queue list la muestra",
    ["Add-on buttons"] = "Botones de addons",
    ["Add-on data"] = "Datos de addons",
    ["Add-on memory"] = "Memoria de addons",
    ["Add-ons"] = "Addons",
    ["Added to the %s checklist: %s"] = "Añadido a la lista %s: %s",
    ["Added."] = "Añadido.",
    ["Address the letter to %s."] = "Dirigir la carta a %s.",
    ["Adds a \"Learn all\" button to the trainer window. It buys every skill you can learn and afford, one after another."] = "Añade un botón «Aprender todo» a la ventana del instructor. Compra una tras otra cada habilidad que puedas aprender y pagar.",
