    ["adventurer"] = "искатель приключений",
    ["%s · %s frames · %d settings, %d switched off"] = "%s · рамки: %s · настроек: %d, выключено: %d",
    ["New in %s"] = "Что нового в %s",
    ["All"] = "Все",
