    ["Tools"] = "Ferramentas",
    ["Tools menu"] = "Menu de ferramentas",
    ["Tools on the Menu button"] = "Ferramentas no botão Menu",
    ["Tooltips"] = "Dicas",
    ["Tooltips appear at the pointer instead of in the bottom-right corner."] = "As dicas aparecem no ponteiro em vez do canto inferior direito.",
    ["Tooltips follow the mouse"] = "Dicas seguem o mouse",
    ["Tooltips: who of your characters can make it"] = "Dicas: qual personagem seu pode fazer",
    ["Total"] = "Total",
