    ["%s an hour"] = "%s all'ora",
    ["%s an hour (%s gold, %s items)"] = "%s all'ora (%s in oro, %s in oggetti)",
    ["%s asks if you are ready."] = "%s chiede se sei pronto.",
    ["%s bosses killed"] = "%s boss uccisi",
    ["%s can drop from your wishlist: %s"] = "%s può lasciare qualcosa della tua lista dei desideri: %s",
    ["%s dungeon and raid runs"] = "%s run in spedizioni e incursioni",
