    ["No switch matches \"%s\"."] = "Nessun interruttore corrisponde a \"%s\".",
    ["No talent build called \"%s\". /fgui talents lists yours."] = "Nessuna build di talenti chiamata \"%s\". /fgui talents elenca le tue.",
    ["no time given"] = "nessuna durata indicata",
    ["No timer started: %s."] = "Nessun timer avviato: %s.",
    ["No timers running. Start one with /fgui timer 5m bread (also 90s, 1h30m, 2:30; a bare number is minutes)."] = "Nessun timer attivo. Avviane uno con /fgui timer 5m bread (anche 90s, 1h30m, 2:30; un numero da solo indica minuti).",
    ["No trades on record yet."] = "Nessuno scambio registrato.",
    ["No tutorial pop-ups"] = "Niente suggerimenti del tutorial",
    ["No upgrades for you from this boss."] = "Nessun miglioramento per te da questo boss.",
    ["No weapon imbue"] = "Nessun potenziamento dell'arma",
    ["No zone's level range is near yours."] = "Nessuna zona vicina al tuo livello.",
    ["nobody"] = "nessuno",
    ["Nobody with the add-on yet"] = "Ancora nessuno con l'add-on",
    ["Nobody yet: the players you group with are listed here."] = "Ancora nessuno: qui compaiono i giocatori con cui fai gruppo.",
    ["None"] = "Nessuno",
    ["none fully on"] = "nessuno indossato per intero",
    ["none known"] = "nessuno noto",
    ["None of your characters is saved to anything."] = "Nessun tuo personaggio è vincolato a qualcosa.",
    ["None yet. Open each profession window once on each character."] = "Ancora niente. Apri ogni finestra professione una volta su ogni personaggio.",
    ["None yet. Rares the alert spots are remembered here."] = "Ancora nessuno. I rari trovati dall'avviso sono ricordati qui.",
